// Agrège les actus RSS et construit le prompt + le corps de requête (compatible OpenAI / Groq).
const items = $input.all().map(i => i.json);
const top = items.slice(0, 10); // plus d'actus pour remplir la page

const liste = top.map((it, n) =>
  `${n + 1}. Titre: ${it.title}\n   URL: ${it.link}\n   Extrait: ${(it.contentSnippet || it.content || '').slice(0, 400)}`
).join('\n\n');

const prompt = `Tu es un rédacteur de veille technologique sur le NUMÉRIQUE QUANTIQUE pour un blog étudiant (BTS SIO).
À partir des actualités ci-dessous, rédige des blocs de veille EN FRANÇAIS, DÉVELOPPÉS et pédagogiques (surtout PAS des résumés d'une seule ligne).

Classe chaque bloc dans l'un des 3 axes :
- "axe1" = architecture matérielle & correction d'erreurs (qubits, FTQC, NISQ, décohérence)
- "axe2" = risque cryptographique & post-quantique (Shor, RSA, PQC, NIST, ANSSI)
- "axe3" = cas d'usage sectoriels & souveraineté (industrie, États, financement)

Objectif : une page BIEN REMPLIE. Produis 2 à 3 blocs PAR axe (6 à 9 blocs au total).
IMPÉRATIF : les TROIS axes (axe1, axe2 ET axe3) doivent CHACUN contenir au moins 2 blocs — ne rends JAMAIS un axe vide. Si l'actualité fournie couvre peu un axe (souvent l'axe3), complète ces blocs avec le contexte général et les enjeux connus du sujet, sans inventer de faits ni de chiffres précis.

Pour chaque bloc :
- "texte" = DÉVELOPPÉ : 1 à 2 paragraphes HTML (<p>...</p><p>...</p>), 5 à 8 phrases au total. Explique le contexte, l'enjeu et les implications (niveau BTS SIO) et mets en <strong> les termes clés. Tu peux ajouter du contexte technique général connu pour étoffer, mais N'INVENTE PAS de faits ni de chiffres précis non fournis.
- "sousTitre" = titre accrocheur commençant par un emoji pertinent.
- Garde TOUJOURS l'URL réelle fournie dans "url". Ignore les actualités hors sujet.

Réponds UNIQUEMENT avec un objet JSON de la forme :
{"blocs":[{"axe":"axe2","type":"section","sousTitre":"🔐 ...","texte":"<p>...</p><p>...</p>","source":"Nom","url":"https://..."}]}

ACTUALITÉS :
${liste}`;

return [{
  json: {
    prompt,
    body: {
      model: "openai/gpt-oss-20b",
      messages: [{ role: "user", content: prompt }],
      temperature: 0.4,
      max_tokens: 16000,
      reasoning_effort: "low"
    }
  }
}];

// Récupère le JSON renvoyé par le modèle (format OpenAI), le nettoie et le transforme en blocs n8n.
const res = $input.first().json;
let text = '';
try {
  text = res.choices[0].message.content;
} catch (e) {
  throw new Error('Réponse LLM inattendue : ' + JSON.stringify(res).slice(0, 500));
}

text = String(text).replace(/```json/gi, '').replace(/```/g, '').trim();

// Extraire le bloc JSON (objet ou tableau) même s'il y a du texte autour.
const firstObj = text.indexOf('{');
const firstArr = text.indexOf('[');
let start = -1;
if (firstObj === -1) start = firstArr;
else if (firstArr === -1) start = firstObj;
else start = Math.min(firstObj, firstArr);
let jsonStr = text;
if (start >= 0) {
  const end = Math.max(text.lastIndexOf('}'), text.lastIndexOf(']'));
  if (end > start) jsonStr = text.slice(start, end + 1);
}

let data;
try {
  data = JSON.parse(jsonStr);
} catch (e) {
  throw new Error('JSON invalide renvoyé par le LLM : ' + text.slice(0, 500));
}

const blocs = Array.isArray(data) ? data : (data.blocs || []);
return blocs.map(b => ({ json: b }));

// Assemble le veille.json au format js/axes.js ET le prépare en fichier binaire.
const blocs = $input.all().map(i => i.json);

const axesMeta = {
  axe1: { numero: 'Axe 1', titre: "Architecture matérielle &amp; correction d'erreurs (FTQC)",
    objectif: 'suivre la transition des calculateurs quantiques « bruités » (ère NISQ) vers des calculateurs tolérants aux pannes (FTQC).' },
  axe2: { numero: 'Axe 2', titre: 'Risque cryptographique &amp; post-quantique (PQC)',
    objectif: 'surveiller la menace quantique sur la sécurité et suivre la migration vers des algorithmes résistants.' },
  axe3: { numero: 'Axe 3', titre: "Cas d'usage sectoriels &amp; souveraineté",
    objectif: "identifier les applications concrètes en entreprise et suivre les stratégies d'investissement des États." }
};

// Photos fixes par axe (déjà présentes dans le dossier, comme la v1)
const imgMap = {
  axe1: 'images/numérique-quantique/reseau-point-lumineux.jpg',
  axe2: 'images/numérique-quantique/crypto-quantique.jpg',
  axe3: 'images/numérique-quantique/usage-quantique.jpg'
};

const now = new Date().toISOString();

const axes = Object.keys(axesMeta).map(id => {
  const meta = axesMeta[id];
  const sousBlocs = blocs
    .filter(b => b.axe === id)
    .map(b => ({ type: b.type || 'section', sousTitre: b.sousTitre, texte: b.texte, source: b.source, url: b.url }));
  return { id, numero: meta.numero, titre: meta.titre, objectif: meta.objectif, image: imgMap[id], horodatage: now, blocs: sousBlocs };
});

const veille = { page: 'quantique', titre: 'Le numérique quantique', derniereMaj: now, axes };

const content = JSON.stringify(veille, null, 2);
const bin = await this.helpers.prepareBinaryData(Buffer.from(content, 'utf-8'), 'veille.json', 'application/json');

return [{ json: veille, binary: { data: bin } }];
